PRAGMA foreign_keys=ON;
CREATE TABLE RoomType(RoomTypeId INTEGER PRIMARY KEY,Name TEXT NOT NULL,BaseRate NUMERIC NOT NULL CHECK(BaseRate>=0),DiscountPercent NUMERIC NOT NULL CHECK(DiscountPercent BETWEEN 0 AND 100));
CREATE TABLE Guest(GuestId INTEGER PRIMARY KEY,FullName TEXT NOT NULL,Phone TEXT NOT NULL,Email TEXT);
CREATE TABLE Room(RoomId INTEGER PRIMARY KEY,RoomTypeId INTEGER NOT NULL REFERENCES RoomType,Number TEXT NOT NULL UNIQUE,Capacity INTEGER NOT NULL CHECK(Capacity>0));
CREATE TABLE Stay(StayId INTEGER PRIMARY KEY,GuestId INTEGER NOT NULL REFERENCES Guest,RoomId INTEGER NOT NULL REFERENCES Room,CheckIn TEXT NOT NULL,CheckOut TEXT NOT NULL,RateSnapshot NUMERIC NOT NULL CHECK(RateSnapshot>=0),DiscountSnapshot NUMERIC NOT NULL CHECK(DiscountSnapshot BETWEEN 0 AND 100),CHECK(CheckOut>CheckIn));
CREATE TABLE Service(ServiceId INTEGER PRIMARY KEY,Name TEXT NOT NULL,UnitPrice NUMERIC NOT NULL CHECK(UnitPrice>=0));
CREATE TABLE StayService(StayServiceId INTEGER PRIMARY KEY,StayId INTEGER NOT NULL REFERENCES Stay,ServiceId INTEGER NOT NULL REFERENCES Service,Quantity NUMERIC NOT NULL CHECK(Quantity>0),UnitPriceSnapshot NUMERIC NOT NULL CHECK(UnitPriceSnapshot>=0));
CREATE TRIGGER stay_no_overlap_insert BEFORE INSERT ON Stay WHEN EXISTS(SELECT 1 FROM Stay s WHERE s.RoomId=NEW.RoomId AND s.CheckIn<NEW.CheckOut AND NEW.CheckIn<s.CheckOut) BEGIN SELECT RAISE(ABORT,'Room occupied'); END;
CREATE TRIGGER stay_no_overlap_update BEFORE UPDATE ON Stay WHEN EXISTS(SELECT 1 FROM Stay s WHERE s.StayId<>NEW.StayId AND s.RoomId=NEW.RoomId AND s.CheckIn<NEW.CheckOut AND NEW.CheckIn<s.CheckOut) BEGIN SELECT RAISE(ABORT,'Room occupied'); END;
